package kr.or.arte.seal.recipient.application;
import kr.or.arte.seal.recipient.crypto.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.UUID;
@Service public class RecipientDeliveryContactQuery{private final RecipientRepository repository;private final PersonalDataCipher cipher;public RecipientDeliveryContactQuery(RecipientRepository r,PersonalDataCipher c){repository=r;cipher=c;}@Transactional(readOnly=true)public RecipientDeliveryContact find(UUID actorId,UUID recipientId){var r=repository.findScoped(actorId,recipientId).orElseThrow(()->new IllegalArgumentException("대상자를 찾을 수 없습니다."));return new RecipientDeliveryContact(r.recipientId(),r.organizationUnitId(),decrypt(r,"name",r.nameCiphertext()),decrypt(r,"email",r.emailCiphertext()));}private String decrypt(RecipientStoredRecord r,String f,byte[] b){return cipher.decrypt(new PersonalDataContext("RECIPIENT",r.recipientId(),r.organizationUnitId(),f),new EncryptedValue(r.encryptionKeyId(),b));}}
